import {categories,summarize,platformOf} from './model.js';
import * as online from './online.js';
import {apiBase} from './config.js';
const apiUrl = path => apiBase + path, mediaUrl = id => apiUrl('/api/media/' + id);
const $=s=>document.querySelector('dialog[open] '+s.replace(/#(field-[\w-]+|record-form|form-error|upload-progress|save-record|file-preview|drop-zone)/g,'#modal-$1'))||document.querySelector(s),h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tabs=[['feedback','Feedback'],['players','Spelare'],['sales','Försäljning'],['codes','Koder'],['budget','Budget'],['content','Video & manus'],['goals','Mål'],['analysis','Analys'],['videos','Videor'],['tests','Speltester & builds'],['overview','Översikt']];
const labels={open:'Öppen',progress:'Pågår',review:'Att verifiera',fixed:'Fixad',new:'Ny',done:'Klar',active:'Aktivt',untested:'Otestad',testing:'Testas',passed:'Godkänd',failed:'Underkänd',planned:'Planerad',blocked:'Blockerad',idea:'Idé',script:'Manus',record:'Inspelning',edit:'Redigering',published:'Publicerad',low:'Låg',normal:'Normal',high:'Hög',critical:'Kritisk',gameplay:'Gameplay',reference:'Referens',milestone:'Milstolpe',number:'Mätbart mål'};
const newNames={goal:'Nytt mål',playtest:'Nytt speltest',settings:'Månadsbudget'};
const names={feedback:'feedback',video:'video',goal:'mål',build:'build',playtest:'speltest',budget:'budgetpost',content:'videoidé',analysis:'analys',settings:'månadsbudget'};
let records=[],section=location.hash.slice(1)||'feedback',search='',filter='all',category='all',loaded=false,toastTimer,formBusy=false,activeVideo=null,previewUrl=null,analysisWeek='',analysisPlatform='TikTok';
try{$('#author').value=localStorage.getItem('shredbound.author')||'William';}catch{}
$('#author').addEventListener('change',()=>{try{localStorage.setItem('shredbound.author',$('#author').value.trim()||'William');}catch{}});
const author=()=>$('#author').value.trim()||'William',of=k=>records.filter(r=>!r.archived&&r.kind===k),byId=id=>records.find(r=>r.id===id),badge=s=>`<span class="badge ${h(s)}">${h(labels[s]||s)}</span>`,date=s=>s?new Intl.DateTimeFormat('sv-SE',{day:'numeric',month:'short'}).format(new Date(/^\d{4}-\d{2}-\d{2}$/.test(s)?s+'T12:00:00':s)):'';
const money=n=>new Intl.NumberFormat('sv-SE',{maximumFractionDigits:0}).format(n)+' kr',count=n=>new Intl.NumberFormat('sv-SE').format(n),time=n=>`${Math.floor(n/60)}:${String(Math.floor(n%60)).padStart(2,'0')}${n%1?'.'+Math.round((n%1)*10):''}`;
const addButton=(kind,label,secondary=false)=>`<button class="button${secondary?' secondary':''}" data-new="${kind}"><span aria-hidden="true">＋</span> ${h(label||'Lägg till '+names[kind])}</button>`;
const editButton=r=>`<button class="button secondary small" data-edit="${r.id}" aria-label="Redigera ${h(r.data.title)}">Redigera</button>`;
const archiveButton=r=>`<button class="text-button" data-archive="${r.id}" aria-label="Arkivera ${h(r.data.title)}">Arkivera</button>`;
const empty=(title,desc,kind)=>`<div class="empty"><div class="empty-mark" aria-hidden="true">↗</div><strong>${h(title)}</strong><p>${h(desc)}</p>${kind?addButton(kind):''}</div>`;
const panel=(title,body,action='')=>`<section class="panel"><div class="panel-header"><h2>${title}</h2>${action}</div>${body}</section>`;
function heading(k,title,description,action=''){return `<div class="page-heading"><h1>${h(tabs.find(t=>t[0]===section)?.[1]||'Shredbound Dashboard')}</h1>${action}</div>`;}
function stat(label,value,caption,accent=false){return `<div class="stat"><div class="stat-label">${label}</div><div class="stat-number ${accent?'accent':''}">${value}</div><div class="stat-caption">${caption}</div></div>`;}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
async function request(path,options){const res=await fetch(apiUrl(path),options);let body;try{body=await res.json();}catch{throw Error('Kunde inte läsa svaret. Kontrollera anslutningen.');}if(!res.ok)throw Error(body.error||'Kunde inte spara. Försök igen.');return body;}
function feedbackDraft(){return section==='feedback'&&!!($('#main #field-details')?.value||$('#main #field-file')?.files.length);}
function connection(state,text){$('#connection').dataset.state=state;$('#connection').textContent=text;}
async function load(silent=false){try{const data=await request('/api/records');const changed=JSON.stringify(records)!==JSON.stringify(data.records);records=data.records;loaded=true;connection('ok','SPARAS ONLINE');if(!silent||changed&&!$('#editor').open&&!$('#viewer').open&&!feedbackDraft())render();}catch(e){connection('error','ANSLUTNING SAKNAS');if(!loaded)$('#main').innerHTML=heading('','','')+`<div class="error">${h(e.message)}</div><button class="button" data-retry>Försök igen</button>`;else if(!silent)toast(e.message);}}
async function patch(r,data,archived){const result=await request('/api/records/'+r.id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision:r.revision,...(data?{data}:{}),...(typeof archived==='boolean'?{archived}:{})})});records=records.map(x=>x.id===r.id?result.record:x);render();return result.record;}
function render(){if(!tabs.some(t=>t[0]===section))section='feedback';const s=summarize(records);$('#navigation').innerHTML=tabs.map(([id,label])=>`<a href="#${id}" ${id===section?'aria-current="page"':''}>${label}${id==='feedback'&&s.open?`<span class="nav-count">${s.open}</span>`:''}${id==='videos'&&s.pendingVideos?`<span class="nav-count">${s.pendingVideos}</span>`:''}</a>`).join('');const views={overview,feedback,videos,goals,tests,analysis,budget,content,players,sales,codes};$('#main').innerHTML=views[section](s);bindFilters();bindOnline();ensureOnline();$('nav a[aria-current]')?.scrollIntoView({block:'nearest',inline:'nearest'});$('#analysis-period')?.addEventListener('change',e=>{analysisWeek=e.target.value;render();});if(section==='feedback'){const form=$('#main #record-form');form.addEventListener('submit',e=>saveForm(e,'feedback',null,defaults('feedback')));const file=$('#main #field-file');file.addEventListener('change',()=>previewFile(file.files[0]));const chooseFile=files=>{if(!files.length)return;file.files=files;previewFile(file.files[0]);};form.addEventListener('dragover',e=>e.preventDefault());form.addEventListener('drop',e=>{e.preventDefault();chooseFile(e.dataTransfer.files);});form.addEventListener('paste',e=>{if(e.clipboardData.files.length){e.preventDefault();chooseFile(e.clipboardData.files);}});}}
function feedbackRow(r){const d=r.data,media=d.mediaId?h(mediaUrl(d.mediaId)):'',isVideo=d.mediaType?.startsWith('video/');return `<article class="row feedback-row" data-fixed="${d.status==='fixed'}"><button class="feedback-check" data-toggle="${r.id}" aria-label="${d.status==='fixed'?'Öppna igen':'Markera fixad'}" aria-pressed="${d.status==='fixed'}">${d.status==='fixed'?'✓':''}</button><div class="row-content"><p class="feedback-text">${h(d.details||(!d.mediaId?d.title:''))}</p>${media?(isVideo?`<video class="feedback-media" controls playsinline preload="metadata" src="${media}"></video>`:`<a href="${media}" target="_blank" rel="noopener"><img class="feedback-media" src="${media}" alt="Bifogad bild" loading="lazy"></a>`):''}<div class="metadata"><span>${h(d.author)} · ${date(r.created_at)}</span>${d.videoId&&byId(d.videoId)?`<button class="timestamp" data-watch="${h(d.videoId)}" data-time="${d.timestamp??0}">▶ ${d.timestamp!=null?time(d.timestamp):'Video'}</button>`:''}${d.status==='fixed'?badge('fixed'):''}</div></div><div class="row-menu">${editButton(r)}</div></article>`;}

function goalCompact(r){const d=r.data,done=d.status==='done'||d.current>=d.target,pct=done?100:Math.min(100,Math.round(d.current/d.target*100));return `<div class="row"><div class="row-content"><div class="row-title">${h(d.title)}</div><div class="goal-value"><span>${d.type==='milestone'?(done?'Klart':'Nästa milstolpe'):`${count(d.current)} / ${count(d.target)} ${h(d.unit)}`}</span><span class="accent">${pct}%</span></div><div class="meter" role="progressbar" aria-label="${h(d.title)}" aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100"><i style="width:${pct}%"></i></div></div></div>`;}
function overview(s){const pending=of('feedback').filter(r=>r.data.status!=='fixed').slice(0,5),gs=of('goal').slice(0,4);return heading('', 'Översikt','')+`<div class="stats">${stat('Öppen feedback',s.open,'')}${stat('Videor',s.videos,'')}${stat('Mål klara',`${s.goalsDone} / ${s.goals}`,'')}${stat('Godkända testförsök',s.testRate===null?'—':s.testRate+'%','')}</div><div class="columns">${panel('Feedback',pending.length?pending.map(feedbackRow).join(''):empty('Ingen öppen feedback',''),'<a class="text-button" href="#feedback">Öppna feedback</a>')}${panel('Mål',gs.length?gs.map(goalCompact).join(''):empty('Inga mål',''),addButton('goal','Nytt mål',true))}</div>`;}

function toolbar(statuses,placeholder='Sök…',showCategory=true){return `<div class="toolbar"><input id="search" type="search" aria-label="Sök" placeholder="${placeholder}" value="${h(search)}">${showCategory?`<select id="category-filter" aria-label="Filtrera spelsystem"><option value="all">Alla spelsystem</option>${categories.map(c=>`<option ${category===c?'selected':''}>${h(c)}</option>`).join('')}</select>`:''}<div class="chips">${[['all','Alla'],...statuses].map(([s,l])=>`<button class="chip" data-filter="${s}" aria-pressed="${s===filter}">${l}</button>`).join('')}</div></div>`;}
function filtered(rows){const query=search.toLocaleLowerCase('sv');return rows.filter(r=>(filter==='all'||r.data.status===filter)&&(category==='all'||r.data.category===category)&&(!query||[r.data.title,r.data.details,r.data.author].join(' ').toLocaleLowerCase('sv').includes(query)));}
function feedback(){return panel('Ny feedback',`<form id="record-form" class="feedback-form"><label class="field" for="field-details"><span>Text</span><textarea id="field-details" name="details" rows="3" placeholder="Skriv feedback…"></textarea></label><input type="file" id="field-file" name="file" accept="image/png,image/jpeg,image/webp,image/gif,video/mp4,video/webm,video/quicktime,.mov" hidden aria-label="Bild eller video"><div id="file-preview"></div><div class="feedback-form-actions"><button type="button" class="button secondary" data-attach>Bifoga bild eller video</button><button type="submit" class="button" id="save-record">Lägg till</button></div><div class="error" id="form-error" role="alert"></div><div id="upload-progress" class="metric-notice" role="status"></div></form>`)+`<div class="subheading"><h2>Feedback</h2><span class="muted">${of('feedback').length} poster</span></div>`+toolbar([['open','Öppen'],['fixed','Fixad']],'Sök feedback…',false)+`<section class="panel" id="result-list">${feedbackList()}</section>`;}
function feedbackList(){const list=filtered(of('feedback'));return list.length?list.map(feedbackRow).join(''):empty(of('feedback').length?'Inga träffar':'Ingen feedback ännu','');}

function videos(){return heading('','','',addButton('video','Lägg till video'))+toolbar([['new','Nya'],['review','Under granskning'],['done','Klara']])+`<div id="result-list">${videoList()}</div>`;}
function videoList(){const list=filtered(of('video'));return list.length?`<div class="cards">${list.map(r=>`<article class="panel"><div class="video-cover"><div class="play-symbol" aria-hidden="true">▶</div><span class="eyebrow">${h(labels[r.data.purpose])}</span><button data-watch="${r.id}" aria-label="Öppna ${h(r.data.title)}"></button></div><div class="card-content"><div class="row-title">${h(r.data.title)}</div><div class="metadata">${badge(r.data.status)}<span>${h(r.data.category)}</span></div><p class="row-desc">${h(r.data.details.slice(0,100)||'')}</p><div class="actions"><button class="button small" data-watch="${r.id}">Granska klipp ↗</button>${editButton(r)}</div></div></article>`).join('')}</div>`:panel('Ditt videobibliotek',empty(of('video').length?'Inga klipp matchar':'Inga videor ännu','Ladda upp MP4, WebM eller MOV. Du kan också klistra in en videolänk.',of('video').length?null:'video'));}
function goals(){const rows=of('goal');return heading('','','',addButton('goal','Nytt mål'))+(rows.length?`<div class="cards">${rows.map(r=>{const d=r.data,done=d.status==='done'||d.current>=d.target;return `<article class="panel goal-card"><div class="card-content"><div class="metadata" style="margin:0 0 14px">${badge(done?'done':'active')}<span>${h(d.category)}</span></div><h3>${h(d.title)}</h3>${d.details?`<p class="row-desc">${h(d.details)}</p>`:''}${goalCompact(r).replace('<div class="row">','<div style="margin-top:8px">')}<div class="metadata"><span>${d.due?'Senast '+date(d.due):'Ingen deadline'}</span><span>${h(d.author)}</span></div><div class="actions">${editButton(r)}<button class="text-button" data-goal="${r.id}">${done?'Återöppna':'Markera klart'}</button>${archiveButton(r)}</div></div></article>`;}).join('')}</div>`:panel('Dina mål',empty('Inga mål ännu','','goal')));}
function tests(){const builds=of('build'),runs=of('playtest');return heading('','','',addButton('playtest','Nytt speltest'))+`<div class="build-test-grid">${panel('Builds',builds.length?`<div class="table-wrap"><table><thead><tr><th>Version</th><th>Plattform</th><th>Status</th><th>Automatiska tester</th><th></th></tr></thead><tbody>${builds.map(r=>`<tr><td><b>${h(r.data.title)}</b><div class="table-sub">${h(r.data.commit||'Commit ej angiven')}</div></td><td>${h(r.data.platform)}</td><td>${badge(r.data.status)}</td><td>${r.data.passed!=null?`${r.data.passed} godkända / ${r.data.failed??'—'} fel`:'Ej registrerat'}</td><td><div class="actions">${r.data.url?`<a class="text-button" target="_blank" rel="noopener" href="${h(r.data.url)}">Öppna ↗</a>`:''}${editButton(r)}</div></td></tr>`).join('')}</tbody></table></div>`:empty('Lägg till versionen du testar','Plattform, commit och testresultat samlas på samma ställe.'),addButton('build','Ny build',true))}${panel('Speltester',runs.length?runs.map(r=>`<article class="row"><div class="row-content"><div class="row-title">${h(r.data.title)}</div><p class="row-desc">${h(r.data.details||'Ingen beskrivning.')}</p><div class="metadata">${badge(r.data.result)}<span>${h(r.data.category)}</span><span>${h(byId(r.data.buildId)?.data.title||'Ingen build kopplad')}</span><span>${r.data.successes}/${r.data.attempts} försök godkända</span>${r.data.fps!=null?`<span>${r.data.fps} FPS (manuellt)</span>`:''}${r.data.videoId?`<button class="timestamp" data-watch="${h(r.data.videoId)}">▶ Video</button>`:''}</div></div><div class="row-menu">${editButton(r)}${archiveButton(r)}</div></article>`).join(''):empty('Inga speltester ännu','','playtest'))}</div>`;}
function currentWeek(){const now=new Date(),start=new Date(now.getFullYear(),now.getMonth(),now.getDate());start.setDate(start.getDate()-((start.getDay()+6)%7));const end=new Date(start);end.setDate(end.getDate()+6);const key=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;return {start:key(start),end:key(end)};}
const dayKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,weekOf=s=>{const d=new Date(s+'T12:00:00');d.setDate(d.getDate()-((d.getDay()+6)%7));return dayKey(d);},weekEnd=s=>{const d=new Date(s+'T12:00:00');d.setDate(d.getDate()+6);return dayKey(d);},span=r=>new Date(r.data.periodEnd)-new Date(r.data.periodStart);
const socialRows=[['views','Visningar'],['likes','Likes'],['comments','Kommentarer'],['shares','Delningar'],['followers','Följare totalt'],['newFollowers','Nya följare']],insightLinks={TikTok:['https://www.tiktok.com/tiktokstudio/analytics/overview','Öppna TikTok Studio'],Instagram:['https://business.facebook.com/latest/insights/','Öppna Instagram-insikter']};
// One dated report per platform per week. Week deltas compare against the same platform's previous report of equal length, never lifetime counts.
function analysis(){const reports=of('analysis').filter(r=>r.data.periodStart&&r.data.periodEnd).sort((a,b)=>b.data.periodEnd.localeCompare(a.data.periodEnd)||b.updated_at.localeCompare(a.updated_at)),weeks=[...new Set(reports.map(r=>weekOf(r.data.periodEnd)))],week=weeks.includes(analysisWeek)?analysisWeek:weeks[0]||currentWeek().start,find=p=>reports.find(r=>weekOf(r.data.periodEnd)===week&&platformOf(r.data)===p),before=r=>r&&reports.find(x=>x!==r&&platformOf(x.data)===platformOf(r.data)&&x.data.periodEnd<r.data.periodStart&&span(x)===span(r)),change=(r,key)=>{const a=before(r)?.data[key],b=r?.data[key];return a==null||b==null?null:b-a;},signed=n=>`${n>0?'+':''}${count(n)}`,delta=(r,key)=>{const n=change(r,key);return n==null?'':`${signed(n)} mot föregående vecka`;},metric=v=>v==null?'—':count(v),platform=analysisPlatform,selected=find(platform),d=selected?.data,range=d?`${date(d.periodStart)} – ${date(d.periodEnd)}`:`${date(week)} – ${date(weekEnd(week))}`,both=[find('TikTok'),find('Instagram')],gs=of('goal'),[insightUrl,insightLabel]=insightLinks[platform];
 const compare=`<div class="table-wrap"><table><thead><tr><th>Mått</th><th class="num">TikTok</th><th class="num">Instagram</th></tr></thead><tbody>${socialRows.map(([k,l])=>`<tr><td>${l}</td>${both.map(r=>{const n=change(r,k);return `<td class="num">${metric(r?.data[k])}${n==null?'':`<div class="table-sub">${signed(n)}</div>`}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div>`;
 return `<div class="page-heading"><h1>${h(platform)} · ${h(d?.account||'Shredbound')}</h1>${weeks.length?`<select id="analysis-period" aria-label="Välj vecka">${weeks.map(w=>`<option value="${w}" ${w===week?'selected':''}>${date(w)} – ${date(weekEnd(w))}</option>`).join('')}</select>`:''}</div><div class="toolbar"><div class="chips">${['TikTok','Instagram'].map(p=>`<button class="chip" data-platform="${p}" aria-pressed="${p===platform}">${p}</button>`).join('')}</div></div><p class="period-label">${range}${d?` · Avläst ${date(d.takenOn)}`:''} · Söndagsanalys</p><div class="stats">${stat('Visningar',metric(d?.views),delta(selected,'views'))}${stat('Likes',metric(d?.likes),delta(selected,'likes'))}${stat('Kommentarer',metric(d?.comments),delta(selected,'comments'))}${stat('Delningar',metric(d?.shares),delta(selected,'shares'))}</div><div class="stats">${stat('Följare totalt',metric(d?.followers),delta(selected,'followers'))}${stat('Nya följare',metric(d?.newFollowers),delta(selected,'newFollowers'))}${stat('Order',metric(d?.orders),d?.orderSource||'')}${stat('Försäljning',d?.revenue==null?'—':`${count(d.revenue)} ${h(d.currency)}`,'')}</div>${!d?`<div class="callout">Ingen veckostatistik för ${h(platform)} ännu. Söndagsanalysen fyller i den när kontot är satt.</div>`:''}<div class="columns"><div class="stack">${panel('AI-analys',d?.conclusion?`<div class="panel-body"><div class="prewrap">${h(d.conclusion)}</div>${d.next?`<hr class="divider"><h2>Nästa steg</h2><p class="prewrap" style="margin-top:12px">${h(d.next)}</p>`:''}<p class="metric-notice">${h(d.analyst)} · ${date(selected.updated_at)}</p></div>`:empty('Ingen analys ännu','Analysen visas när veckans siffror har lästs av.'))}${d?.topVideos?.length?panel('Inlägg denna period',`<div class="table-wrap"><table><thead><tr><th>Inlägg</th><th class="num">Visningar</th><th class="num">Likes</th></tr></thead><tbody>${d.topVideos.map(v=>`<tr><td>${v.url?`<a href="${h(v.url)}" target="_blank" rel="noopener">${h(v.title||'Inlägg')}</a>`:h(v.title||'Inlägg')}</td><td class="num">${metric(v.views)}</td><td class="num">${metric(v.likes)}</td></tr>`).join('')}</tbody></table></div>`):''}</div><div class="stack">${panel('Veckan per plattform',compare)}${panel('Mål',gs.length?gs.map(goalCompact).join(''):empty('Inga mål ännu',''))}${panel('Underlag',`<div class="panel-body">${d?`<p class="prewrap">${h(d.evidence||d.dataSource||'Källa ej angiven')}</p>`:'<p class="metric-notice" style="margin-top:0">Ingen avläsning ännu.</p>'}<div class="actions" style="margin-top:12px">${d?.profileUrl?`<a class="text-button" href="${h(d.profileUrl)}" target="_blank" rel="noopener">${h(platform)}-konto</a>`:''}<a class="text-button" href="${insightUrl}" target="_blank" rel="noopener">${insightLabel}</a></div></div>`)}</div></div>`;}

function budget(s){const rows=of('budget'),setting=of('settings')[0],limit=setting?.data.monthlyBudget||0,pct=limit?Math.min(100,s.expense/limit*100):0,month=new Intl.DateTimeFormat('sv-SE',{month:'long',year:'numeric'}).format(new Date());return heading('','','',addButton('budget','Ny budgetpost'))+`<div class="stats">${stat('Utgifter denna månad',money(s.expense),month)}${stat('Intäkter denna månad',money(s.income),month)}${stat('Netto',money(s.net),'Intäkter minus utgifter',true)}${stat('Månadsbudget',limit?money(limit):'Ej satt','Sätt en ram för månaden')}</div>${panel('Månadens utrymme',`<div class="panel-body"><div class="goal-value" style="margin-top:0"><span>${money(s.expense)} ${limit?'av '+money(limit):'· budget saknas'}</span><span>${limit?Math.round(s.expense/limit*100)+'%':'—'}</span></div><div class="meter"><i style="width:${pct}%"></i></div>${limit&&s.expense>limit?'<p class="metric-notice">Utgifterna är högre än månadsbudgeten.</p>':''}</div>`,setting?editButton(setting):addButton('settings','Sätt budget',true))}<div class="subheading"><h2>Alla poster</h2><span class="eyebrow">SEK</span></div><section class="panel">${rows.length?`<div class="table-wrap"><table><thead><tr><th>Post</th><th>Kategori</th><th>Datum</th><th>Belopp</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${h(r.data.title)}</b><div class="table-sub">${h(r.data.author)}</div></td><td>${h(r.data.budgetCategory)}</td><td>${date(r.data.date)}</td><td class="num ${r.data.type==='income'?'accent':''}">${r.data.type==='expense'?'−':'+'}${money(r.data.amount)}</td><td>${editButton(r)}</td></tr>`).join('')}</tbody></table></div>`:empty('Inga budgetposter ännu','','budget')}</section>`;}
function content(){const rows=of('content'),views=rows.reduce((n,r)=>n+r.data.views,0),likes=rows.reduce((n,r)=>n+r.data.likes,0);return heading('','','',addButton('content','Ny videoidé'))+`<div class="stats">${stat('Idéer & klipp',rows.length,'Hela innehållsflödet')}${stat('Publicerade',rows.filter(r=>r.data.status==='published').length,'Markerade publicerade')}${stat('Registrerade visningar',count(views),'Manuellt inmatade siffror',true)}${stat('Likes per visning',views?(likes/views*100).toFixed(1)+'%':'—','Summerade likes / visningar')}</div><div class="kanban">${['idea','script','record','edit','published'].map(status=>`<section class="lane"><div class="lane-head"><span>${labels[status].toUpperCase()}</span><span>${rows.filter(r=>r.data.status===status).length}</span></div>${rows.filter(r=>r.data.status===status).map(r=>`<article class="content-card"><div class="row-title">${h(r.data.title)}</div><p class="row-desc">${h((r.data.hook||r.data.details).slice(0,110))}</p><div class="metadata">${h(r.data.platform)}</div><div class="actions">${editButton(r)}</div></article>`).join('')||'<p class="metric-notice">Inget här ännu.</p>'}</section>`).join('')}</div>`;}
// Spelare, Försäljning och Koder: Supabase edge functions "access" and "store-stats".
// Admin data needs the secret from the ADMIN field (localStorage only, see online.js).
const net={pub:null,admin:null,store:null,errors:{},at:{},loading:new Set()},onlineSections=['players','sales','codes'];let pendingConfirm=null,resizeTimer;
const dash=v=>v==null?'—':count(v),hoursText=s=>{const n=online.hours(s);return n==null?'—':`${n<10?n.toLocaleString('sv-SE',{maximumFractionDigits:1}):count(Math.round(n))}<span class="unit">h</span>`;},hoursPlain=s=>{const n=online.hours(s);return n==null?'—':(n<10?n.toLocaleString('sv-SE',{maximumFractionDigits:1}):count(Math.round(n)))+' h';};
const validDate=s=>s&&!Number.isNaN(new Date(s).getTime()),when=s=>validDate(s)?new Intl.DateTimeFormat('sv-SE',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(s)):'—',onDay=s=>validDate(s)?date(new Date(s).toISOString()):'—';
const shortId=id=>id.length>12?id.slice(0,8)+'…':id,notice=(e,label)=>`<div class="error">${h(label)}: ${h(e.message)}</div>`,busy=()=>net.loading.size?'<span class="eyebrow">Hämtar…</span>':'';
const codeBadge=c=>c.revoked?'<span class="badge failed">Återkallad</span>':validDate(c.expires)&&new Date(c.expires)<new Date()?'<span class="badge blocked">Utgången</span>':'<span class="badge passed">Aktiv</span>';
async function fetchNet(key,force=false){
 const secret=online.adminSecret();if(key==='admin'&&!secret)return;if(net.loading.has(key)||(!force&&net.at[key]&&Date.now()-net.at[key]<60000))return;net.loading.add(key);
 try{
  if(key==='pub')net.pub=online.normalizeTotals(await online.call('access','public.stats'));
  if(key==='admin')net.admin=online.normalizeAdmin(await online.call('access','admin.stats',{},secret));
  if(key==='store'){let body;try{body=await online.call('store-stats',secret?'admin.stats':'public.stats',{},secret);}catch(e){if(!secret||![401,403].includes(e.status))throw e;body=await online.call('store-stats','public.stats');}net.store=online.normalizeStore(body);}
  delete net.errors[key];
 }catch(e){net.errors[key]=e;if(key==='admin')net.admin=null;}
 finally{net.loading.delete(key);net.at[key]=Date.now();if(onlineSections.includes(section)&&!$('#editor').open&&!$('#viewer').open)render();}
}
function ensureOnline(){if(section==='players'){fetchNet('pub');fetchNet('store');fetchNet('admin');}if(section==='sales')fetchNet('store');if(section==='codes')fetchNet('admin');}
function chartSize(){const m=$('#main'),cs=getComputedStyle(m),width=Math.max(280,Math.round(m.clientWidth-parseFloat(cs.paddingLeft)-parseFloat(cs.paddingRight)-34));return {width,height:width<560?170:220};}
function players(){const a=net.admin,t=a?.totals||net.pub||{},st=net.store,err=!a&&net.errors.pub;return heading('','','',busy())+(err?notice(err,'Spelardata'):'')+(net.errors.admin?notice(net.errors.admin,'Admin'):'')+`<div class="stats">${stat('Enheter',dash(t.devices),'Datorer som startat speltestet')}${stat('Speltid',hoursText(t.playSeconds),'Alla enheter, totalt')}${stat('Aktiva 7 dagar',dash(t.active7d),a&&t.activeToday!=null?`${count(t.activeToday)} aktiva idag`:'Spelat senaste veckan')}${stat('Nedladdningar',dash(st?.totals.downloads),st?.connected?'itch.io, alla spel':'itch.io ej kopplat')}</div>`+(a?playerAdmin(a):panel('Speltid per dag',`<div class="panel-body"><p class="metric-notice" style="margin-top:0">Speltid per dag och per kod visas med admin-nyckeln.</p><a class="text-button" href="#codes">Lås upp under Koder</a></div>`));}
function playerAdmin(a){const rows=online.fillDays(a.daily,60),played=rows.filter(r=>r.seconds||r.devices).reverse();return panel('Speltid per dag',`<div class="panel-body"><div id="play-chart">${online.dailyChart(rows,chartSize())}</div><details class="data-table"><summary>Visa som tabell</summary>${played.length?`<div class="table-wrap"><table><thead><tr><th>Dag</th><th class="num">Speltid</th><th class="num">Enheter</th></tr></thead><tbody>${played.map(r=>`<tr><td>${date(r.day)}</td><td class="num">${hoursPlain(r.seconds)}</td><td class="num">${count(r.devices)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="metric-notice">Ingen speltid de senaste 60 dagarna.</p>'}</details></div>`,`<span class="eyebrow" id="chart-readout">Senaste 60 dagarna</span>`)+`<div class="subheading"><h2>Per kod</h2><span class="muted">${a.codes.length} koder</span></div><section class="panel">${a.codes.length?`<div class="table-wrap"><table><thead><tr><th>Kod</th><th>Status</th><th class="num">Enheter</th><th class="num">Speltid</th><th>Senast spelad</th></tr></thead><tbody>${a.codes.map(c=>`<tr><td><b>${h(c.name||'Namnlös')}</b></td><td>${codeBadge(c)}</td><td class="num">${dash(c.devices)}</td><td class="num">${hoursPlain(c.playSeconds)}</td><td>${when(c.lastSeen)}</td></tr>`).join('')}</tbody></table></div>`:empty('Inga koder ännu','')}</section>`;}
function connectPanel(secret){return panel('Koppla itch.io',`<div class="panel-body"><p>Nedladdningar, köp och intäkter hämtas från itch.io med en API-nyckel (itch.io → Settings → API keys).</p>${secret?`<form id="store-key-form" class="inline-form"><label class="field" for="store-key"><span>itch.io API-nyckel</span><input id="store-key" type="password" autocomplete="off" required></label><button class="button" type="submit">Koppla</button></form><div class="error" id="store-error" role="alert"></div><p class="metric-notice">Nyckeln sparas bara på servern och visas aldrig här igen.</p>`:'<a class="text-button" href="#codes" style="display:inline-block;margin-top:12px">Lås upp med admin-nyckeln under Koder</a>'}</div>`);}
function sales(){const st=net.store,err=net.errors.store,secret=online.adminSecret(),head=heading('','','',busy());if(!st&&!err)return head+panel('itch.io','<div class="loading">Hämtar…</div>');if(!st)return head+notice(err,'Försäljning')+connectPanel(secret);if(!st.connected)return head+(st.error?`<div class="error">${h(st.error)}</div>`:'')+connectPanel(secret);const e=st.earnings,earned=e==null?'—':e.length?e.map(online.formatEarning).join(' + '):'0 kr';return head+(st.error?`<div class="error">${h(st.error)}</div>`:'')+`<div class="stats">${stat('Nedladdningar',dash(st.totals.downloads),'Alla spel')}${stat('Sidvisningar',dash(st.totals.views),'itch.io-sidorna')}${stat('Köp',dash(st.totals.purchases),'Betalda köp')}${stat('Intäkter',earned,e==null?'Visas med admin-nyckeln':'Totalt, enligt itch.io',e!=null)}</div><section class="panel">${st.games.length?`<div class="table-wrap"><table><thead><tr><th>Spel</th><th class="num">Nedladdningar</th><th class="num">Sidvisningar</th><th class="num">Köp</th>${e!=null?'<th class="num">Intäkter</th>':''}</tr></thead><tbody>${st.games.map(g=>`<tr><td>${g.url?`<a href="${h(g.url)}" target="_blank" rel="noopener"><b>${h(g.title)}</b></a>`:`<b>${h(g.title)}</b>`}</td><td class="num">${dash(g.downloads)}</td><td class="num">${dash(g.views)}</td><td class="num">${dash(g.purchases)}</td>${e!=null?`<td class="num">${g.earnings?.length?g.earnings.map(online.formatEarning).join(' + '):'0'}</td>`:''}</tr>`).join('')}</tbody></table></div>`:empty('Inga spel på itch.io ännu','Spelen visas här när de finns på kontot.')}</section><div class="actions" style="margin-top:12px"><span class="metric-notice" style="margin:0">Från itch.io · uppdaterat ${when(st.updatedAt)}</span>${e!=null?'<button class="text-button" data-store-disconnect>Koppla bort itch.io</button>':''}</div>`;}
function codes(){const secret=online.adminSecret(),a=net.admin,err=net.errors.admin;if(!secret)return heading('','','')+panel('Admin',`<form id="admin-form" class="panel-body"><div class="inline-form"><label class="field" for="admin-secret"><span>Admin-nyckel</span><input id="admin-secret" type="password" autocomplete="off" required></label><button class="button" type="submit">Lås upp</button></div><div class="error" id="admin-error" role="alert"></div><p class="metric-notice">Sparas bara i den här webbläsaren och skickas bara till Shredbounds egna funktioner.</p></form>`);const head=heading('','','',`<div class="actions">${busy()}<button class="text-button" data-admin-forget>Glöm admin-nyckeln</button><button class="button" data-code-new><span aria-hidden="true">＋</span> Ny kod</button></div>`);if(!a)return head+(err?notice(err,'Koder'):panel('Koder','<div class="loading">Hämtar…</div>'));const devices=a.devices;return head+`<section class="panel">${a.codes.length?`<div class="table-wrap"><table><thead><tr><th>Kod</th><th>Status</th><th class="num">Enheter</th><th class="num">Speltid</th><th>Skapad</th><th>Går ut</th><th class="col-actions"></th></tr></thead><tbody>${a.codes.map(c=>{const act=c.revoked?`<button class="button secondary small" data-code-restore="${h(c.id)}" data-name="${h(c.name)}">Återställ</button>`:`<button class="button secondary small" data-code-revoke="${h(c.id)}" data-name="${h(c.name)}">Återkalla</button>`;return `<tr><td><b>${h(c.name||'Namnlös')}</b>${c.days!=null?`<div class="table-sub">${count(c.days)} dagar per enhet</div>`:''}<div class="actions mobile-only">${act}</div></td><td>${codeBadge(c)}</td><td class="num">${dash(c.devices)}</td><td class="num">${hoursPlain(c.playSeconds)}</td><td>${onDay(c.created)}</td><td>${validDate(c.expires)?onDay(c.expires):'Aldrig'}</td><td class="col-actions"><div class="actions">${act}</div></td></tr>`;}).join('')}</tbody></table></div>`:empty('Inga koder ännu','Skapa en kod och dela den med speltestarna.')}</section><div class="subheading"><h2>Enheter</h2><span class="muted">${devices.length} enheter</span></div><section class="panel">${devices.length?`<div class="table-wrap"><table><thead><tr><th>Enhet</th><th>Kod</th><th class="num">Speltid</th><th>Senast</th><th>Går ut</th><th class="col-actions"></th></tr></thead><tbody>${devices.map(d=>{const act=d.banned?`<button class="button secondary small" data-device-unban="${h(d.id)}">Häv bannlysning</button>`:`<button class="button secondary small" data-device-ban="${h(d.id)}">Bannlys</button>`;return `<tr><td><span class="mono" title="${h(d.id)}">${h(shortId(d.id))}</span>${d.banned?' <span class="badge failed">Bannlyst</span>':''}${d.platform||d.version?`<div class="table-sub">${h([d.platform,d.version].filter(Boolean).join(' · '))}</div>`:''}<div class="actions mobile-only">${act}</div></td><td>${h(d.code||'—')}</td><td class="num">${hoursPlain(d.playSeconds)}</td><td>${when(d.lastSeen)}</td><td>${onDay(d.expires)}</td><td class="col-actions"><div class="actions">${act}</div></td></tr>`;}).join('')}</tbody></table></div>`:empty('Inga enheter ännu','Enheter visas när någon startar spelet med en kod.')}</section>`;}
function dialogShell(title,body,footer){return `<header class="dialog-header"><div><h2 id="dialog-title">${h(title)}</h2></div><button class="icon-button" type="button" data-close="editor" aria-label="Stäng">×</button></header><div class="dialog-body">${body}</div><footer class="dialog-footer">${footer}</footer>`;}
function confirmAction(title,text,label,run){pendingConfirm=run;$('#viewer').close();const d=$('#editor');d.innerHTML=dialogShell(title,`<p class="confirm-text">${h(text)}</p><div class="error" id="confirm-error" role="alert"></div>`,`<button class="button secondary" type="button" data-close="editor">Avbryt</button><button class="button" type="button" data-confirm>${h(label)}</button>`);d.showModal();}
function openCodeForm(){$('#viewer').close();const d=$('#editor');d.innerHTML=`<form id="code-form">${dialogShell('Ny kod',`<div class="form-grid"><label class="field wide" for="code-name"><span>Namn</span><input id="code-name" name="name" required maxlength="40" placeholder="Vem koden är till"></label><label class="field" for="code-value"><span>Egen kod (valfri)</span><input id="code-value" name="code" minlength="4" maxlength="40" pattern="[A-Za-z0-9_\-]{4,40}" title="4–40 tecken: bokstäver, siffror, - och _" autocomplete="off" placeholder="Skapas automatiskt"></label><label class="field" for="code-days"><span>Dagar per enhet</span><input id="code-days" name="days" type="number" min="1" max="3650" step="1" value="14" required></label><label class="field" for="code-expires"><span>Koden går ut (valfritt)</span><input id="code-expires" name="expires" type="date"></label></div><div class="error" id="code-error" role="alert"></div>`,`<button class="button secondary" type="button" data-close="editor">Avbryt</button><button class="button" type="submit" id="code-save">Skapa kod</button>`)}</form>`;d.showModal();$('#code-form').addEventListener('submit',createCode);}
async function createCode(e){e.preventDefault();if(formBusy)return;formBusy=true;const button=$('#code-save'),fd=new FormData(e.target),name=String(fd.get('name')).trim(),custom=String(fd.get('code')||'').trim(),days=Number(fd.get('days')),expires=String(fd.get('expires')||'');button.disabled=true;button.textContent='Skapar…';$('#code-error').textContent='';try{const payload={name,days};if(custom)payload.code=custom;if(expires)payload.expiresAt=new Date(expires+'T23:59:59').toISOString();const code=online.createdCode(await online.call('access','admin.create',payload));$('#editor').innerHTML=dialogShell('Kod skapad',`<p class="row-desc" style="margin:0">${h(name)} · ${count(days)} dagar per enhet</p>${code?`<div class="code-reveal"><code id="new-code">${h(code)}</code><button class="button" type="button" data-copy>Kopiera</button></div><p class="metric-notice">Koden visas bara nu. Kopiera den innan du stänger.</p>`:'<p class="metric-notice">Koden skapades, men svaret innehöll ingen kod.</p>'}`,`<button class="button" type="button" data-close="editor">Klar</button>`);fetchNet('admin',true);}catch(err){$('#code-error').textContent=err.message;button.disabled=false;button.textContent='Skapa kod';}finally{formBusy=false;}}
async function unlockAdmin(e){e.preventDefault();const input=$('#admin-secret'),value=input.value.trim(),button=e.target.querySelector('button[type=submit]');if(!value)return;button.disabled=true;$('#admin-error').textContent='';try{const body=await online.call('access','admin.stats',{},value);online.setAdminSecret(value);net.admin=online.normalizeAdmin(body);delete net.errors.admin;net.at.admin=Date.now();net.at.store=0;toast('Admin upplåst i den här webbläsaren.');render();}catch(err){$('#admin-error').textContent=err.message;input.select();}finally{if(button.isConnected)button.disabled=false;}}
async function connectStore(e){e.preventDefault();const input=$('#store-key'),key=input.value.trim(),button=e.target.querySelector('button');if(!key)return;button.disabled=true;$('#store-error').textContent='';try{net.store=online.normalizeStore(await online.call('store-stats','admin.setKey',{key}));input.value='';net.at.store=Date.now();toast('itch.io kopplat.');render();}catch(err){input.value='';$('#store-error').textContent=err.message;}finally{if(button.isConnected)button.disabled=false;}}
function bindOnline(){$('#admin-form')?.addEventListener('submit',unlockAdmin);$('#store-key-form')?.addEventListener('submit',connectStore);}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const ds=b.dataset;try{
 if(ds.platform){analysisPlatform=ds.platform;render();return;}
 if(b.hasAttribute('data-code-new'))return openCodeForm();
 if(b.hasAttribute('data-admin-forget')){online.setAdminSecret('');net.admin=null;delete net.errors.admin;net.at.store=0;render();return toast('Admin-nyckeln är borttagen från den här webbläsaren.');}
 if(b.hasAttribute('data-copy')){const node=$('#new-code');if(!node)return;try{await navigator.clipboard.writeText(node.textContent);toast('Koden är kopierad.');}catch{if(!node.isConnected)return toast('Kunde inte kopiera koden.');const r=document.createRange();r.selectNodeContents(node);getSelection().removeAllRanges();getSelection().addRange(r);toast('Markerad. Kopiera med ⌘C.');}return;}
 const after=(message,key='admin')=>()=>{toast(message);fetchNet(key,true);};
 if(ds.codeRevoke)return confirmAction('Återkalla kod',`Koden ”${ds.name}” slutar fungera tills du återställer den.`,'Återkalla',()=>online.call('access','admin.revoke',{id:ds.codeRevoke}).then(after('Koden är återkallad.')));
 if(ds.codeRestore)return confirmAction('Återställ kod',`Koden ”${ds.name}” fungerar igen.`,'Återställ',()=>online.call('access','admin.restore',{id:ds.codeRestore}).then(after('Koden är återställd.')));
 if(ds.deviceBan)return confirmAction('Bannlys enhet',`Enheten ${shortId(ds.deviceBan)} kan inte längre starta spelet.`,'Bannlys',()=>online.call('access','admin.ban',{device:ds.deviceBan}).then(after('Enheten är bannlyst.')));
 if(ds.deviceUnban)return confirmAction('Häv bannlysning',`Enheten ${shortId(ds.deviceUnban)} kan starta spelet igen.`,'Häv bannlysning',()=>online.call('access','admin.unban',{device:ds.deviceUnban}).then(after('Bannlysningen är hävd.')));
 if(b.hasAttribute('data-store-disconnect'))return confirmAction('Koppla bort itch.io','Nyckeln tas bort från servern. Försäljningen visas inte förrän du kopplar en ny nyckel.','Koppla bort',()=>online.call('store-stats','admin.clearKey').then(after('itch.io är bortkopplat.','store')));
 if(b.hasAttribute('data-confirm')&&pendingConfirm){if(formBusy)return;formBusy=true;b.disabled=true;$('#confirm-error').textContent='';try{const run=pendingConfirm;await run();pendingConfirm=null;formBusy=false;$('#editor').close();}catch(err){$('#confirm-error').textContent=err.message;}finally{formBusy=false;if(b.isConnected)b.disabled=false;}}
}catch(err){toast(err.message);}});
document.addEventListener('pointerover',e=>{const g=e.target.closest?.('.chart-col'),out=$('#chart-readout');if(g&&out)out.textContent=`${date(g.dataset.day)} · ${g.dataset.hours} h · ${g.dataset.devices} enheter`;});
window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{const c=$('#play-chart');if(c&&net.admin)c.innerHTML=online.dailyChart(online.fillDays(net.admin.daily,60),chartSize());},150);});
function bindFilters(){const input=$('#search');input?.addEventListener('input',()=>{search=input.value;$('#result-list').innerHTML=section==='feedback'?feedbackList():videoList();});$('#category-filter')?.addEventListener('change',e=>{category=e.target.value;$('#result-list').innerHTML=section==='feedback'?feedbackList():videoList();});}
