function defaults(kind){return {title:kind==='settings'?'Månadsbudget':'',author:author(),category:categories[0],status:{feedback:'open',video:'new',goal:'active',build:'untested',content:'idea'}[kind],priority:'normal',purpose:'gameplay',type:kind==='budget'?'expense':'number',target:1,current:0,attempts:1,successes:0,result:'planned',views:0,likes:0,platform:kind==='content'?'TikTok':'Windows',date:new Date().toLocaleDateString('en-CA'),monthlyBudget:0};}
function fieldMarkup(f,d){const value=d[f.key]??'',attrs=`name="${f.key}" id="field-${f.key}" ${f.required?'required':''} ${f.max?`maxlength="${f.max}"`:''}`;if(f.type==='file')return `<div class="field wide"><label class="upload-zone" id="drop-zone"><strong>${f.label}</strong><small>eller välj fil · max 50 MB</small><input ${attrs} type="file" accept="${f.accept}" aria-label="${f.label}"></label>${d.mediaId?'<small>Befintlig bilaga behålls om du inte väljer en ny fil.</small>':''}<div id="file-preview"></div></div>`;let input;if(f.type==='select')input=`<select ${attrs}>${f.options.map(([v,t])=>`<option value="${h(v)}" ${String(v)===String(value)?'selected':''}>${h(t)}</option>`).join('')}</select>`;else if(f.type==='textarea')input=`<textarea ${attrs} rows="${f.key==='script'?8:3}" placeholder="${h(f.placeholder||'')}">${h(value)}</textarea>`;else input=`<input ${attrs} type="${f.type}" value="${h(value)}" placeholder="${h(f.placeholder||'')}" ${f.min!=null?`min="${f.min}"`:''} ${f.type==='number'&&f.max?`max="${f.max}"`:''} ${f.step?`step="${f.step}"`:''}>`;return `<label class="field ${f.wide?'wide':''}" for="field-${f.key}"><span>${h(f.label)}</span>${input}</label>`;}
function openEditor(kind,id=null,prefill={}){if(!loaded)return toast('Vänta på anslutningen innan du lägger till något.');const r=id?byId(id):null,data={...defaults(kind),...r?.data,...prefill};$('#viewer').close();const dialog=$('#editor');dialog.innerHTML=`<form id="record-form"><header class="dialog-header"><div><div class="eyebrow" style="margin-bottom:8px">${r?'REDIGERA':'LÄGG TILL'}</div><h2 id="dialog-title">${kind==='feedback'?(r?'Redigera feedback':'Ny feedback'):r?h(r.data.title):h(newNames[kind]||('Ny '+names[kind]))}</h2></div><button class="icon-button" type="button" data-close="editor" aria-label="Stäng">×</button></header><div class="dialog-body"><div class="form-grid">${fields(kind).map(f=>fieldMarkup(f,data)).join('')}</div>${kind==='goal'?'<p class="metric-notice">För en milstolpe används 0 = inte klart och 1 = klart.</p>':''}<div class="error" id="form-error" role="alert"></div><div id="upload-progress" class="metric-notice" role="status"></div></div><footer class="dialog-footer">${r?`<button type="button" class="text-button" data-archive="${r.id}" style="margin-right:auto">Arkivera</button>`:''}<button class="button secondary" type="button" data-close="editor">Avbryt</button><button class="button" id="save-record" type="submit">${r?'Spara ändringar':'Spara '+h(names[kind])}</button></footer></form>`.replace(/\bid="(field-[^"\s]+|record-form|form-error|upload-progress|save-record|file-preview|drop-zone)"/g,'id="modal-$1"').replace(/\bfor="(field-[^"\s]+)"/g,'for="modal-$1"');dialog.showModal();$('#record-form').addEventListener('submit',e=>saveForm(e,kind,r,data));const fi=$('#field-file');if(fi){fi.addEventListener('change',()=>previewFile(fi.files[0]));const dz=$('#drop-zone');dz.addEventListener('dragover',e=>{e.preventDefault();dz.dataset.over='true';});dz.addEventListener('dragleave',()=>dz.dataset.over='false');dz.addEventListener('drop',e=>{e.preventDefault();dz.dataset.over='false';if(e.dataTransfer.files.length){fi.files=e.dataTransfer.files;previewFile(fi.files[0]);}});}if(kind==='goal'){$('#field-type').addEventListener('change',()=>{const milestone=$('#field-type').value==='milestone';if(milestone){$('#field-target').value='1';$('#field-current').value='0';$('#field-unit').value='';}$('#field-target').readOnly=milestone;$('#field-current').readOnly=milestone;});}}
function previewFile(file){if(previewUrl)URL.revokeObjectURL(previewUrl);if(!file)return;if(file.size>50*1024*1024){$('#form-error').textContent='Filen är större än 50 MB. Välj ett kortare klipp eller använd en videolänk.';return;}$('#form-error').textContent='';previewUrl=URL.createObjectURL(file);$('#file-preview').innerHTML=file.type.startsWith('image/')?`<img src="${previewUrl}" class="file-preview" alt="Förhandsvisning av vald bilaga">`:file.type.startsWith('video/')?`<video src="${previewUrl}" controls class="file-preview"></video>`:`<p class="metric-notice">${h(file.name)}</p>`;}
function upload(file){return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST',apiUrl('/api/media'));xhr.setRequestHeader('Content-Type',file.type||(/\.mov$/i.test(file.name)?'video/quicktime':'application/octet-stream'));xhr.setRequestHeader('X-Filename',encodeURIComponent(file.name));xhr.upload.onprogress=e=>{if(e.lengthComputable)$('#upload-progress').textContent=`Laddar upp… ${Math.round(e.loaded/e.total*100)}%`;};xhr.onload=()=>{try{const body=JSON.parse(xhr.responseText);if(xhr.status<200||xhr.status>=300)reject(Error(body.error||'Uppladdningen misslyckades.'));else resolve(body);}catch{reject(Error('Uppladdningen misslyckades. Försök igen.'));}};xhr.onerror=()=>reject(Error('Anslutningen bröts under uppladdningen. Försök igen.'));xhr.timeout=180000;xhr.ontimeout=()=>reject(Error('Uppladdningen tog för lång tid. Försök igen.'));xhr.send(file);});}
async function saveForm(e,kind,r,original){e.preventDefault();if(formBusy)return;formBusy=true;const button=$('#save-record');button.disabled=true;button.textContent='Sparar…';$('#form-error').textContent='';try{const fd=new FormData(e.target),data={...original,author:r?.data.author||author()};for(const f of fields(kind))if(f.type!=='file')data[f.key]=fd.get(f.key)??'';if(kind==='goal'&&data.type==='milestone'){data.target=1;data.current=data.status==='done'?1:0;}if(kind==='feedback')data.title='';const file=fd.get('file');if(file?.size){if(file.size>50*1024*1024)throw Error('Filen får vara högst 50 MB.');const media=await upload(file);data.mediaId=media.id;data.mediaType=media.mime;original.mediaId=media.id;original.mediaType=media.mime;$('#field-file').value='';}if(r)await patch(r,data);else{const result=await request('/api/records',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind,data})});records.unshift(result.record);render();}if($('#editor').open)$('#editor').close();else render();toast('Sparat.');}catch(err){$('#form-error').textContent=err.message;}finally{formBusy=false;if(button.isConnected){button.disabled=false;button.textContent='Spara';}}}
function embedFor(url){try{const u=new URL(url);let id;if(['www.youtube.com','youtube.com','m.youtube.com'].includes(u.hostname))id=u.searchParams.get('v')||u.pathname.match(/^\/(?:shorts|embed)\/([^/]+)/)?.[1];if(u.hostname==='youtu.be')id=u.pathname.slice(1);if(id&&/^[\w-]{11}$/.test(id))return 'https://www.youtube-nocookie.com/embed/'+id;if(['vimeo.com','www.vimeo.com'].includes(u.hostname)&&/^\/\d+$/.test(u.pathname))return 'https://player.vimeo.com/video'+u.pathname;}catch{}return null;}
function watch(id,start=0){const r=byId(id);if(!r)return toast('Videon finns inte.');activeVideo=id;const d=r.data,src=d.mediaId?mediaUrl(d.mediaId):d.url,embed=embedFor(src),native=!!d.mediaId||/\.(mp4|webm|mov)(\?|#|$)/i.test(src);$('#editor').close();$('#viewer').className='viewer';$('#viewer').innerHTML=`<header class="dialog-header"><div><div class="eyebrow" style="margin-bottom:8px">${h(labels[d.purpose])} / ${h(d.category)}</div><h2 id="viewer-title">${h(d.title)}</h2></div><button class="icon-button" data-close="viewer" aria-label="Stäng video">×</button></header><div class="viewer-grid"><div class="viewer-video">${native?`<video id="review-player" class="video-player" src="${h(src)}" controls playsinline preload="metadata"></video><div class="video-tools"><button class="button secondary small" data-seek="-0.1" aria-label="Bakåt 0,1 sekunder">− 0,1 s</button><button class="button secondary small" data-seek="0.1" aria-label="Framåt 0,1 sekunder">+ 0,1 s</button><select id="playback-rate" aria-label="Uppspelningshastighet"><option value="0.25">0,25×</option><option value="0.5">0,5×</option><option value="1" selected>1×</option><option value="1.5">1,5×</option></select><span id="current-time" class="eyebrow">0:00</span></div>`:embed?`<iframe class="embed" src="${h(embed)}" title="${h(d.title)}" allow="fullscreen" allowfullscreen></iframe>`:`<div class="external-video"><p class="row-desc">Öppna videon hos källan och ange tidsstämpeln i feedbacken.</p><a class="button secondary" href="${h(src)}" target="_blank" rel="noopener" style="margin-top:16px">Öppna videolänk ↗</a></div>`}<div id="player-error" class="error" hidden>Videon kunde inte spelas här. Prova MP4/H.264 eller öppna originalfilen.</div><p class="row-desc" style="margin:18px 0">${h(d.details)}</p><div class="actions"><button class="button" data-annotate="${r.id}">＋ Feedback ${native?'vid denna tid':'med tidsstämpel'}</button><button class="button secondary" data-video-done="${r.id}">${d.status==='done'?'Öppna granskning igen':'Markera granskad'}</button></div>${!native?'<p class="metric-notice">Tid från externa spelare anges manuellt i feedbackformuläret.</p>':''}<a class="text-button" href="${h(src)}" target="_blank" rel="noopener" style="display:inline-block;margin-top:14px">Öppna original ↗</a></div><div class="viewer-notes"><div class="panel-header"><h2>Observationer</h2><span class="eyebrow">${of('feedback').filter(f=>f.data.videoId===id).length}</span></div>${videoNotes(id)}</div></div>`;$('#viewer').showModal();const player=$('#review-player');if(player){player.addEventListener('loadedmetadata',()=>{player.currentTime=Math.min(start,Number.isFinite(player.duration)?player.duration:start);});player.addEventListener('timeupdate',()=>$('#current-time').textContent=time(player.currentTime));player.addEventListener('error',()=>$('#player-error').hidden=false);$('#playback-rate').addEventListener('change',e=>player.playbackRate=Number(e.target.value));}}
function videoNotes(id){const notes=of('feedback').filter(f=>f.data.videoId===id).sort((a,b)=>(a.data.timestamp??0)-(b.data.timestamp??0));return notes.length?notes.map(r=>`<div class="row"><div class="row-content">${r.data.timestamp!=null?`<button class="timestamp" data-jump="${r.data.timestamp}">${time(r.data.timestamp)}</button>`:''}<p class="row-title" style="margin-top:8px">${h(r.data.title)}</p><p class="row-desc">${h(r.data.details)}</p><div class="metadata">${badge(r.data.status)}<span>${h(r.data.author)}</span></div><div class="actions" style="margin-top:12px">${editButton(r)}</div></div></div>`).join(''):empty('Ingen feedback på videon','');}
function openArchive(){const rows=records.filter(r=>r.archived);$('#viewer').close();$('#editor').innerHTML=`<header class="dialog-header"><h2 id="dialog-title">Arkiv</h2><button class="icon-button" data-close="editor" aria-label="Stäng">×</button></header><div class="archive-list">${rows.length?rows.map(r=>`<div class="row"><div class="row-content"><div class="row-title">${h(r.data.title)}</div><div class="metadata">${h(names[r.kind])} · ${date(r.updated_at)}</div></div><button class="button secondary small" data-restore="${r.id}">Återställ</button></div>`).join(''):empty('Arkivet är tomt','Arkiverade poster kan återställas här.')}</div>`;$('#editor').showModal();}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{
 if(b.hasAttribute('data-attach'))return $('#field-file').click();
 if(b.dataset.new)return openEditor(b.dataset.new);
 if(b.dataset.edit){const r=byId(b.dataset.edit);return openEditor(r.kind,r.id);}
 if(b.dataset.close){if(formBusy)return;return $('#'+b.dataset.close).close();}
 if(b.hasAttribute('data-retry'))return load();
 if(b.dataset.filter){filter=b.dataset.filter;render();return;}
 if(b.dataset.watch)return watch(b.dataset.watch,Number(b.dataset.time||0));
 if(b.dataset.annotate){const r=byId(b.dataset.annotate),t=$('#review-player')?.currentTime;return openEditor('feedback',null,{videoId:r.id,category:r.data.category,buildId:r.data.buildId,timestamp:t==null?'':Math.round(t*10)/10});}
 if(b.dataset.seek){const p=$('#review-player');p.pause();p.currentTime=Math.min(Number.isFinite(p.duration)?p.duration:86400,Math.max(0,p.currentTime+Number(b.dataset.seek)));return;}
 if(b.dataset.jump){const p=$('#review-player');if(p){p.currentTime=Number(b.dataset.jump);p.pause();}else toast('Tidsstämpel: '+time(Number(b.dataset.jump)));return;}
 if(!['toggle','goal','videoDone','archive','restore'].some(key=>b.dataset[key]))return;
 b.disabled=true;
 if(b.dataset.toggle){const r=byId(b.dataset.toggle);await patch(r,{...r.data,status:r.data.status==='fixed'?'open':'fixed'});toast('Status sparad.');}
 if(b.dataset.goal){const r=byId(b.dataset.goal),done=r.data.status==='done'||r.data.current>=r.data.target;await patch(r,{...r.data,status:done?'active':'done',current:done?0:r.data.target});toast('Målet uppdaterat.');}
 if(b.dataset.videoDone){const r=byId(b.dataset.videoDone);await patch(r,{...r.data,status:r.data.status==='done'?'review':'done'});watch(r.id);toast('Granskning sparad.');}
 if(b.dataset.archive){const r=byId(b.dataset.archive);await patch(r,null,true);$('#editor').close();toast('Arkiverat. Kan återställas i Arkiv.');}
 if(b.dataset.restore){const r=byId(b.dataset.restore);await patch(r,null,false);openArchive();toast('Återställt.');}
 }catch(err){toast(err.message);}finally{if(b.isConnected)b.disabled=false;}});
$('#export-link').href=apiUrl('/api/export');
$('#refresh').addEventListener('click',()=>{net.at={};load();});$('#archive-open').addEventListener('click',openArchive);
$('#editor').addEventListener('cancel',e=>{if(formBusy)e.preventDefault();});$('#editor').addEventListener('close',()=>{if(previewUrl){URL.revokeObjectURL(previewUrl);previewUrl=null;}});$('#editor').addEventListener('close',()=>{pendingConfirm=null;if($('#editor #new-code'))$('#editor').innerHTML='';if(onlineSections.includes(section)&&!$('#viewer').open)render();});$('#viewer').addEventListener('close',()=>{$('#review-player')?.pause();$('#viewer').innerHTML='';activeVideo=null;});
